import type { PlayerId } from '@/types/domain';

// Shared by client and server: do not import Leaflet here.

/** Player slots of a team: the host plus up to two friends. */
export const PLAYER_IDS: readonly PlayerId[] = ['p1', 'p2', 'p3'];
export const MAX_PLAYERS = PLAYER_IDS.length;

/** Spectators watching one team at the same time (they can see everything but change nothing). */
export const MAX_SPECTATORS = 20;

export const TEAM_NAME_MAX_LENGTH = 10;
/** Team passwords are generated by the server: this many letters from TEAM_PASSWORD_ALPHABET. */
export const TEAM_PASSWORD_LENGTH = 6;
/** A–Z without I and O, which are easy to mistake for 1 and 0. */
export const TEAM_PASSWORD_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
export const TEAMS_PAGE_SIZE = 20;

/** GitHub repo whose releases carry the Windows overlay installer (tags `overlay-v…`). */
export const OVERLAY_REPO = 'fresnohernandez99/elden-coop-helper';

/** Your progress is saved to the database at most this often, and only when it changed. */
export const PERSIST_INTERVAL_MS = 2 * 60_000;

/** A player counts as online if they synced within this window (~6 polls). */
export const ONLINE_WINDOW_MS = 20_000;

/** Pin coordinates range from 0 to 256, matching the zoom-0 tile. */
export const MAP_SIZE = 256;
export const MAP_MAX_ZOOM = 7;
export const FOCUS_ZOOM = 4;

export const POLL_INTERVAL_MS = 3000;
export const NOTE_MAX_LENGTH = 140;
export const CHARACTER_NAME_MAX_LENGTH = 32;
export const SEARCH_MIN_LENGTH = 2;
export const SEARCH_MAX_RESULTS = 40;
